import hashlib, subprocess, shutil, os
LEAN='def gate (n r : Nat) (p q : Nat → Prop) (h : Nat) : Prop :=\n  ∀ g, g < h → g < n ∨ (p g ∧ (q g ∨ ¬ ∀ j, j + r ≤ g → q j))\ndef blend (S : Nat → Prop) (a b : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ a h) ∨ (¬ S h ∧ b h)\ndef eventual (p : Nat → Prop) : Prop := ∃ H, ∀ h, H ≤ h → p h\ndef dbtrace (n k : Nat) (S : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ h < k) ∨ (¬ S h ∧ h ≤ n)\ndef selfeq (n r k : Nat) (S d x : Nat → Prop) : Prop :=\n  ∀ h, x h ↔ blend S (fun h => ∀ g, g + k ≤ h → x g) (gate n r x d) h\n\ntheorem hole_window (r t : Nat) (d : Nat → Prop)\n    (pre : ∀ j, j < t → d j) (hole : ¬ d t) (g : Nat) :\n    (d g ∨ ¬ ∀ j, j + r ≤ g → d j) ↔ (d g ∨ t + r ≤ g) := by\n  classical\n  constructor\n  · intro H\n    rcases H with hd | hd\n    · exact Or.inl hd\n    · right\n      by_cases ht : t + r ≤ g\n      · exact ht\n      · exact False.elim (hd (fun j hj => pre j (by omega)))\n  · intro H\n    rcases H with hd | ht\n    · exact Or.inl hd\n    · exact Or.inr (fun H => hole (H t ht))\n\ntheorem least_failure (d : Nat → Prop) (b : Nat) (hb : ¬ d b) :\n    ∃ t, t ≤ b ∧ ¬ d t ∧ ∀ j, j < t → d j := by\n  classical\n  induction b using Nat.strongRecOn with\n  | ind b ih =>\n    by_cases H : ∀ j, j < b → d j\n    · exact ⟨b, Nat.le_refl b, hb, H⟩\n    · obtain ⟨j, hj⟩ := Classical.not_forall.mp H\n      have hjb : j < b := Classical.byContradiction (fun hh => hj (fun h => False.elim (hh h)))\n      have hjd : ¬ d j := fun hd => hj (fun _ => hd)\n      obtain ⟨t, ht, hdt, hp⟩ := ih j hjb hjd\n      exact ⟨t, by omega, hdt, hp⟩\n\ntheorem v_self_law (n r k : Nat) (hk : 1 ≤ k) (S d x : Nat → Prop)\n    (eqn : selfeq n r k S d x) :\n    eventual x ↔ ∀ g, n ≤ g → (¬ d g ∧ (∀ j, j + r ≤ g → d j)) →\n      ∀ h, g < h → S h := by\n  classical\n  constructor\n  · intro ⟨H, hH⟩ g gn bad h gh\n    apply Classical.byContradiction\n    intro sh\n    have nx : ¬ x h := by\n      intro xh\n      rcases (eqn h).1 xh with ⟨hs, _⟩ | ⟨_, hw⟩\n      · exact sh hs\n      · rcases hw g gh with hn | ⟨_, hd⟩\n        · omega\n        · rcases hd with hd | hd\n          · exact bad.1 hd\n          · exact hd bad.2\n    let z := H+h+n+k+1\n    rcases (eqn z).1 (hH z (by dsimp [z]; omega)) with ⟨_, hf⟩ | ⟨_, hw⟩\n    · exact nx (hf h (by dsimp [z]; omega))\n    · rcases hw h (by dsimp [z]; omega) with hn | hh\n      · omega\n      · exact nx hh.1\n  · intro good\n    have allx : ∀ h, x h := by\n      intro h\n      induction h using Nat.strongRecOn with\n      | ind h ih =>\n        apply (eqn h).2\n        by_cases sh : S h\n        · exact Or.inl ⟨sh, fun g gh => ih g (by omega)⟩\n        · refine Or.inr ⟨sh, ?_⟩\n          intro g gh\n          by_cases gn : g < n\n          · exact Or.inl gn\n          · apply Or.inr\n            refine ⟨ih g gh, ?_⟩\n            by_cases dg : d g\n            · exact Or.inl dg\n            · exact Or.inr (fun hd => sh (good g (by omega) ⟨dg, hd⟩ h gh))\n    exact ⟨0, fun h _ => allx h⟩\n#print axioms v_self_law\n#print axioms hole_window\n\ntheorem dbtrace_semantics (n r k : Nat) (S : Nat → Prop) (h : Nat) :\n    blend S (fun h => ∀ g, g + k ≤ h → False)\n      (gate n r (fun _ => False) (fun _ => False)) h ↔ dbtrace n k S h := by\n  have hf : (∀ g, g + k ≤ h → False) ↔ h < k := by\n    constructor\n    · intro H; by_cases e : h < k; exact e; exact False.elim (H 0 (by omega))\n    · intro e g hg; omega\n  have hw : gate n r (fun _ => False) (fun _ => False) h ↔ h ≤ n := by\n    constructor\n    · intro H\n      by_cases hh : h ≤ n\n      · exact hh\n      · rcases H n (by omega) with hn | hf\n        · omega\n        · exact False.elim hf.1\n    · intro H g gh; exact Or.inl (by omega)\n  unfold blend dbtrace\n  dsimp only\n  rw [hf, hw]\n\ntheorem trace_first_exists (n k : Nat) (S : Nat → Prop) :\n    ∃ t, t ≤ n+k+1 ∧ ¬ dbtrace n k S t ∧ ∀ j, j < t → dbtrace n k S j := by\n  apply least_failure (dbtrace n k S) (n+k+1)\n  intro H\n  rcases H with ⟨_, H⟩ | ⟨_, H⟩ <;> omega\n\ntheorem early_iff (n k t : Nat) (S : Nat → Prop)\n    (pre : ∀ j, j < t → dbtrace n k S j) (hole : ¬ dbtrace n k S t) :\n    t < n ↔ ∃ j, k ≤ j ∧ j < n ∧ S j := by\n  classical\n  constructor\n  · intro tn\n    have st : S t := Classical.byContradiction (fun ns => hole (Or.inr ⟨ns, by omega⟩))\n    have kt : k ≤ t := by\n      by_cases tk : t < k\n      · exact False.elim (hole (Or.inl ⟨st, tk⟩))\n      · omega\n    exact ⟨t, kt, tn, st⟩\n  · intro ⟨j, jk, jn, sj⟩\n    by_cases jt : j < t\n    · rcases pre j jt with ⟨_, e⟩ | ⟨ns, _⟩\n      · omega\n      · exact False.elim (ns sj)\n    · omega\n#print axioms dbtrace_semantics\n#print axioms trace_first_exists\n#print axioms early_iff\n\ntheorem fb_partner (n r k : Nat) (hk : 1 ≤ k) (hn : r + 1 ≤ n) (S x y : Nat → Prop)\n    (ex : ∀ h, x h ↔ blend S (fun h => ∀ g, g + k ≤ h → y g)\n       (gate n r y (fun g => g = 0)) h)\n    (ey : ∀ h, y h ↔ ∀ g, g < h → x g) :\n    ∀ h, x h ∧ y h := by\n  classical\n  intro h\n  induction h using Nat.strongRecOn with\n  | ind h ih =>\n    constructor\n    · apply (ex h).2\n      by_cases sh : S h\n      · exact Or.inl ⟨sh, fun g gh => (ih g (by omega)).2⟩\n      · refine Or.inr ⟨sh, ?_⟩\n        intro g gh\n        by_cases gn : g < n\n        · exact Or.inl gn\n        · exact Or.inr ⟨(ih g gh).2, Or.inr (fun H => by have := H 1 (by omega); omega)⟩\n    · exact (ey h).2 (fun g gh => (ih g gh).1)\n\ntheorem cb_partner (n r k : Nat) (S : Nat → Prop) :\n    ∀ h, blend S (fun h => ∀ g, g + k ≤ h → True)\n      (gate n r (fun _ => True) (fun _ => True)) h := by\n  classical\n  intro h\n  by_cases sh : S h\n  · exact Or.inl ⟨sh, fun _ _ => trivial⟩\n  · exact Or.inr ⟨sh, fun _ _ => Or.inr ⟨trivial, Or.inl trivial⟩⟩\n\n#print axioms fb_partner\n#print axioms cb_partner\n\ntheorem v_unexploitable (n r k : Nat) (S p q x : Nat → Prop)\n    (eqn : ∀ h, x h ↔ blend S (fun h => ∀ g, g+k ≤ h → p g) (gate n r p q) h)\n    (pd : eventual (fun g => ¬ p g)) : eventual (fun h => ¬ x h) := by\n  obtain ⟨H, hH⟩ := pd\n  refine ⟨H+n+k+1, ?_⟩\n  intro h hh hx\n  rcases (eqn h).1 hx with ⟨_, hf⟩ | ⟨_, hw⟩\n  · exact hH (H+n) (by omega) (hf (H+n) (by omega))\n  · rcases hw (H+n) (by omega) with hn | hp\n    · omega\n    · exact hH (H+n) (by omega) hp.1\n#print axioms v_unexploitable\n\ntheorem finite_law (n r k t M : Nat) (hk : 1 ≤ k) (S d x : Nat → Prop)\n    (finiteS : ∀ h, M ≤ h → ¬ S h)\n    (pre : ∀ j, j < t → d j) (hole : ¬ d t)\n    (eqn : selfeq n r k S d x) :\n    eventual x ↔ ∀ g, n ≤ g → d g ∨ t+r ≤ g := by\n  classical\n  rw [v_self_law n r k hk S d x eqn]\n  constructor\n  · intro good g gn\n    by_cases dg : d g\n    · exact Or.inl dg\n    · right\n      by_cases tg : t+r ≤ g\n      · exact tg\n      · have bad : ∀ j, j+r ≤ g → d j := fun j hj => pre j (by omega)\n        exact False.elim (finiteS (M+g+1) (by omega) (good g gn ⟨dg,bad⟩ (M+g+1) (by omega)))\n  · intro good g gn bad h gh\n    rcases good g gn with dg | tg\n    · exact False.elim (bad.1 dg)\n    · exact False.elim (hole (bad.2 t tg))\n#print axioms finite_law\n\ntheorem singleton_arithmetic (n r s : Nat) (hr : 1 ≤ r) (hs : 1 ≤ s) (sn : s ≤ n) :\n    (∀ g, n ≤ g → (g ≠ s ∧ g ≤ n) ∨ s+r ≤ g) ↔\n    (s < n ∧ s+r ≤ n+1) := by\n  constructor\n  · intro H\n    have a := H n (Nat.le_refl n)\n    have b := H (n+1) (by omega)\n    constructor <;> rcases a with a | a <;> rcases b with b | b <;> omega\n  · intro H g gn\n    by_cases gsn : g = n\n    · subst g\n      exact Or.inl ⟨by omega, Nat.le_refl n⟩\n    · exact Or.inr (by omega)\n\n#print axioms singleton_arithmetic\n\ntheorem singleton_self (n r s : Nat) (hr : 1 ≤ r) (hs : 1 ≤ s) (sn : s ≤ n)\n    (x : Nat → Prop)\n    (eqn : selfeq n r 1 (fun h => h = s) (dbtrace n 1 (fun h => h = s)) x) :\n    eventual x ↔ s < n ∧ s+r ≤ n+1 := by\n  classical\n  have dd : ∀ h, dbtrace n 1 (fun h => h = s) h ↔ h ≠ s ∧ h ≤ n := by\n    intro h\n    unfold dbtrace\n    constructor\n    · intro H\n      rcases H with ⟨e, hh⟩ | H\n      · omega\n      · exact H\n    · intro H; exact Or.inr H\n  have pre : ∀ j, j < s → dbtrace n 1 (fun h => h = s) j := by\n    intro j hj; exact (dd j).2 ⟨by omega, by omega⟩\n  have hole : ¬ dbtrace n 1 (fun h => h = s) s := fun H => ((dd s).1 H).1 rfl\n  rw [finite_law n r 1 s (s+1) (by omega) (fun h => h=s) _ x\n    (fun h hh hs => by omega) pre hole eqn]\n  simp only [dd]\n  exact singleton_arithmetic n r s hr hs sn\n#print axioms singleton_self\n'
assert hashlib.sha256(LEAN.encode()).hexdigest()=='476df06b363401b409647558154a17172c73eeb3a1fd0143e9a8e87ad3b68ffd'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r = subprocess.run([binary, '--stdin'], input=LEAN, text=True, capture_output=True, timeout=90)
assert r.returncode == 0, r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms') == 11

for old,new in [('s < n ∧ s+r ≤ n+1', 's ≤ n ∧ s+r ≤ n+1'), ('(hk : 1 ≤ k)', '(hk : 0 ≤ k)'), ('(hn : r + 1 ≤ n)', '(hn : r ≤ n)')]:
 bad=LEAN.replace(old,new)
 assert bad!=LEAN
 r=subprocess.run([binary,"--stdin"],input=bad,text=True,capture_output=True,timeout=15)
 assert r.returncode!=0,"mutation accepted"
print("PASS: 11 Lean theorems, 3 rejected mutations")
